import { useEffect, useState } from 'react';

export type Language = 'pl' | 'en';
const KEY = 'joypad.language';
export const LANGUAGES: Record<Language, string> = { pl: 'Polski', en: 'English' };

export function loadLanguage(): Language {
  try { return localStorage.getItem(KEY) === 'en' ? 'en' : 'pl'; } catch { return 'pl'; }
}

export function setLanguage(language: Language) {
  try { localStorage.setItem(KEY, language); } catch { /* optional */ }
  window.dispatchEvent(new CustomEvent('joypad-language', { detail: language }));
}

export function useLanguage() {
  const [language, setState] = useState<Language>(loadLanguage);
  useEffect(() => {
    const update = (event: Event) => setState((event as CustomEvent<Language>).detail || loadLanguage());
    window.addEventListener('joypad-language', update);
    return () => window.removeEventListener('joypad-language', update);
  }, []);
  return language;
}

