export function t(language: Language, key: string, values: Record<string, string | number> = {}): string {
  let value = messages[language][key] ?? messages.pl[key] ?? key;
  for (const [name, replacement] of Object.entries(values)) value = value.split(`{${name}}`).join(String(replacement));
  return value;
}

export function useT() {
  const language = useLanguage();
  return { language, t: (key: string, values?: Record<string, string | number>) => t(language, key, values) };
}

